'use strict';
const PAGE=document.body.dataset.page;
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pages={start:'index.html',candidates:'course-candidates.html',stays:'stays.html',detail:'stay-detail.html',payment:'payment.html',complete:'complete.html',mypage:'mypage.html',reservations:'reservations.html',courses:'my-courses.html',posts:'my-posts.html'};
const regions=['부산광역시','제주 제주시','제주 서귀포시','강원 강릉시','서울특별시','광주광역시','경기 광주시'];
const spots={부산:['광안리 해변','부산시립미술관','전포 카페거리'],제주:['해안 산책로','지역 전시관','동네 식당'],강원:['경포해변','실내 전시관','안목 커피거리'],서울:['서울숲','서울시립미술관','성수 골목'],광주:['도심 산책로','지역 미술관','전통시장'],경기:['경안천 산책로','실내 전시관','지역 식당']};
const uid=()=>Date.now().toString(36)+Math.random().toString(36).slice(2,7);
const seed=()=>({draft:{},bookings:[{id:'sample-completed',region:'부산광역시',date:'2026-10-10',nights:1,guests:2,companion:'친구',transport:'대중교통',stay:'부산 여행 스테이',room:'스탠다드',price:110000,status:'숙박완료',versions:[{name:'바다와 골목 여행',v:1,note:'최초 코스',time:'2026-10-10',places:['광안리 해변','부산시립미술관','전포 카페거리']}],post:{title:'친구와 다녀온 부산 여행',body:'해변을 걷고 골목에서 식사하며 여유롭게 보낸 여행입니다.',photo:'',version:1}}],notify:true,login:true});
let state;try{state=JSON.parse(decodeURIComponent(location.hash.slice(1)));if(!state?.bookings)throw Error()}catch{try{state=JSON.parse(localStorage.getItem('smart-travel-map-ver9'))}catch{}if(!state?.bookings)state=seed()}
let draft=state.draft||{};state.draft=draft;
function save(){state.draft=draft;try{localStorage.setItem('smart-travel-map-ver9',JSON.stringify(state))}catch{}try{history.replaceState(null,'','#'+encodeURIComponent(JSON.stringify(state)))}catch{}}
function go(p){save();location.href=pages[p]+'#'+encodeURIComponent(JSON.stringify(state))}
const money=n=>Number(n).toLocaleString('ko-KR')+'원';
function msg(t,error=false){$('#feedback').innerHTML=`<div class="message ${error?'error':''}" role="status">${esc(t)}</div>`;$('#feedback').scrollIntoView({block:'nearest',behavior:'smooth'})}
function hero(k,t,sub=''){return `<div class="hero"><span class="eyebrow">${k}</span><h1>${t}</h1><p>${sub}</p></div>`}
function btn(a,t,cls='primary',extra=''){return `<button type="button" class="${cls}" data-action="${a}" ${extra}>${t}</button>`}
function link(p,t,cls='secondary'){return `<a class="${cls}" href="${pages[p]}" data-go="${p}">${t}</a>`}
function opts(xs,value){return xs.map(x=>`<option ${x===value?'selected':''}>${esc(x)}</option>`).join('')}
function conditions(){return `<div class="summary">${[draft.region,draft.nights===0?'당일':draft.nights+'박 '+(Number(draft.nights)+1)+'일',draft.companion,draft.transport,draft.date||'출발 날짜 미정',draft.guests?draft.guests+'명':'인원 미정'].filter(Boolean).map(x=>`<span>${esc(x)}</span>`).join('')}</div>`}
function fields(full=true){return `<div class="fields"><label>지역<select name="region">${opts(regions,draft.region||'부산광역시')}</select></label><label>여행 기간<select name="nights">${[0,1,2,3].map(n=>`<option value="${n}" ${Number(draft.nights??1)===n?'selected':''}>${n===0?'당일':n+'박 '+(n+1)+'일'}</option>`).join('')}</select></label><label>동행<select name="companion">${opts(['혼자','친구','연인','가족'],draft.companion||'친구')}</select></label><label>교통수단<select name="transport">${opts(['대중교통','자가용'],draft.transport||'대중교통')}</select></label>${full?`<label>출발 날짜 <span class="muted">(선택)</span><input name="date" type="date" min="${today()}" value="${esc(draft.date||'')}"></label><label>인원 <span class="muted">(선택)</span><input type="number" name="guests" min="1" max="10" placeholder="인원 선택" value="${esc(draft.guests||'')}"></label>`:''}</div>`}
function today(){let d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function readForm(form){const f=new FormData(form);draft={...draft,region:f.get('region'),nights:+f.get('nights'),companion:f.get('companion'),transport:f.get('transport'),date:f.get('date')||'',guests:f.get('guests')?+f.get('guests'):null};delete draft.selected;delete draft.stay;delete draft.room;delete draft.candidates;delete draft.hold;delete draft.orderId;save()}
function icon(chat){return chat?'<svg class="icon" viewBox="0 0 80 70" fill="none" aria-hidden="true"><path d="M36 49H20l-9 7 3-13C-1 20 16 7 34 10c11 0 18 4 22 11" stroke="currentColor" stroke-width="3"/><path d="M44 29c30-8 38 22 19 29l4 8-13-6C26 62 23 35 44 29Z" fill="#c8f2e7"/><circle cx="43" cy="44" r="2" fill="#09836d"/><circle cx="53" cy="44" r="2" fill="#09836d"/><circle cx="63" cy="44" r="2" fill="#09836d"/></svg>':'<svg class="icon" viewBox="0 0 80 70" fill="none" aria-hidden="true"><path d="M7 15h66M7 35h66M7 55h66" stroke="currentColor" stroke-width="3" stroke-linecap="round"/><circle cx="27" cy="15" r="8" fill="white" stroke="currentColor" stroke-width="3"/><circle cx="53" cy="35" r="8" fill="#bdeee1" stroke="#09836d" stroke-width="3"/><circle cx="25" cy="55" r="8" fill="#bdeee1" stroke="currentColor" stroke-width="3"/></svg>'}
function start(){return hero('01　시작 방식 선택형','취향은 당신이, 여행 코스는 <em>AI가.</em>','새로운 코스를 찾고, 내 일정을 편하게 바꿔보세요.')+`<h2 class="section-title">어떤 방식으로 여행을 시작할까요?</h2><div class="grid"><section class="card choice">${icon(true)}<h2>대화로 추천받기</h2><p>원하는 여행을 편하게 이야기해 주세요.</p><form id="chat-form"><label for="chat">어떤 여행을 원하시나요?</label><textarea id="chat" name="chat" placeholder="친구와 부산 1박 2일 여행을 가고 싶어요" required></textarea><div class="actions"><button class="primary" type="submit">대화 시작하기　→</button></div><details><summary>응답이 지연되거나 실패했나요?</summary><p class="note">조건 선택 방식으로 동일한 조건을 확인하고 진행할 수 있습니다.</p>${btn('chat-fail','조건 선택으로 전환','text-button')}</details></form></section><section class="card choice">${icon(false)}<h2>조건 선택으로 추천받기</h2><p>필요한 조건을 골라 빠르게 추천받으세요.</p><form id="condition-form">${fields()}<div class="actions"><button class="primary" type="submit">조건으로 추천받기　→</button></div><button class="text-button" type="button" data-action="stay-first">숙소 먼저 고르기</button></form></section></div><div class="tip">♧　입력 방식은 달라도, 같은 여행 일정으로 이어져요.</div><section id="extracted" class="card" hidden><h2>추출된 조건을 확인해주세요</h2><p id="chat-result" class="muted"></p><form id="confirm-chat"></form></section>`}
function getPlaces(){return spots[Object.keys(spots).find(k=>(draft.region||'').includes(k))]||spots.부산}
function timeline(course,adjusted=false,context=draft){const ps=course?.places||getPlaces();let blocks='';const count=Number(context.nights??1)+1;for(let day=1;day<=count;day++){blocks+=`<h3>${day}일차</h3><ul class="timeline">${(day===1?[[adjusted?'10:30':'10:00',ps[0]],[adjusted?'14:30':'14:00',ps[1]],...(adjusted?[['15:00','숙소 체크인']]:[]),['17:00',ps[2]]]:day===count?[['09:00','숙소 주변 아침 식사'],['11:00','체크아웃 · 귀가']]:[['10:00',ps[1]],['12:30','지역 식당'],['15:00',ps[2]]]).map(([time,p])=>`<li><strong>${time}</strong><p>${esc(p)}</p></li>`).join('')}</ul>`}return blocks}
function candidates(){if(!draft.region)return guard();if(draft.flow==='stay'&&!draft.stay)return guard();return hero('02　AI 코스 만들기',draft.flow==='stay'?'선택한 숙소에서 시작하는 <em>여행.</em>':'마음에 드는 코스를 <em>골라보세요.</em>','미리보기와 선택만으로는 내 코스에 저장되지 않습니다.')+conditions()+`<div class="tip">${draft.date?'출발 날짜 기준 날씨와 교통수단을 반영하는 샘플입니다.':'출발 날짜가 없어 날씨는 반영하지 않았습니다.'} ${draft.flow==='stay'?'숙소 위치와 체크인·체크아웃 시각을 함께 반영합니다.':''}</div><div class="actions">${btn('generate','샘플 코스 생성하기')}${btn('generation-fail','생성 실패 상황 보기','secondary')}</div><div id="course-results">${candidateCards()}</div>`}
function candidateCards(){if(!draft.candidates)return '<div class="empty">코스를 생성하면 비교할 수 있는 후보가 표시됩니다.</div>';return `<div class="grid three" style="margin-top:22px">${draft.candidates.map((c,i)=>`<section class="card"><span class="pill">코스 ${i+1}</span><h2>${esc(c.name)}</h2><p class="muted">${esc(draft.transport)} 기준 · ${esc(draft.companion)} 여행</p>${draft.flow==='course'?`<p class="note">주변 예약 가능 숙소: ${draft.date&&draft.guests?(draft.guests>4?'0곳':'2곳 (샘플)'):'날짜·인원 확인 후 조회'}</p>`:''}<details><summary>일정 미리보기</summary>${timeline(c,draft.flow==='stay')}</details>${btn('select-course',draft.flow==='stay'?'이 코스로 예약하기':'이 코스 선택하기','primary',`data-index="${i}"`)}</section>`).join('')}</div>`}
function dateGuests(){return `<form id="date-guests" class="card"><h2>숙소 조회를 위한 조건 확인</h2><p class="muted">선택한 날짜 전체에 머무는 숙소 한 곳을 추천합니다.</p><div class="fields"><label>출발 날짜<input name="date" type="date" required min="${today()}" value="${esc(draft.date||'')}"></label><label>인원<input name="guests" type="number" min="1" max="10" required value="${esc(draft.guests||'')}"></label></div><button class="primary" style="margin-top:20px">조건 확인 · 숙소 조회</button></form>`}
function stays(){if(!draft.region)return guard();if(draft.nights===0)return hero('당일 여행','당일 코스를 <em>확인하세요.</em>','숙박 예약 없이 후보를 살펴볼 수 있습니다.')+conditions()+`<section class="card"><p>당일 여행에는 숙소 예약을 진행하지 않습니다. 숙박이 필요하면 기간을 변경해주세요.</p><div class="actions">${link('start','여행 조건 변경')}${link('candidates','코스 보기')}</div></section>`;if(draft.flow==='course'&&!draft.selected)return guard('먼저 코스 후보 한 개를 선택해주세요.','candidates');return hero('03　숙소 찾기',draft.flow==='course'?'내 코스 가까이에, <em>편안한 쉼.</em>':'여행의 시작이 될 <em>숙소.</em>','추천 시점의 예약 가능 여부는 확보가 아니며 예약 요청 시 다시 확인합니다.')+conditions()+`<div style="margin-top:25px">${dateGuests()}</div>${draft.date&&draft.guests?stayCards():''}`}
function stayCards(){if(draft.guests>4)return `<div class="card" style="margin-top:20px"><h2>조건에 맞는 숙소가 없습니다</h2><p>추천 범위를 확대했지만 조건에 맞는 샘플 객실이 없습니다.</p><div class="actions">${btn('expand','범위 확대 다시 확인','secondary')}${link('candidates','다른 코스 선택')}${btn('regional','지역 숙소 목록','secondary')}</div><p class="note">날짜 또는 인원을 변경해 다시 조회해주세요.</p></div>`;let arr=[{id:0,name:draft.region+' 가든 스테이',price:110000,time:draft.transport==='자가용'?12:22},{id:1,name:draft.region+' 어반 호텔',price:95000,time:draft.transport==='자가용'?19:31}];if(draft.sort==='price')arr.sort((a,b)=>a.price-b.price);return `<div class="row" style="margin:24px 0 15px"><h2>${draft.flow==='course'?'코스 주변 숙소':'지역 숙소 목록'} <span class="muted">2곳</span></h2><label>정렬<select id="stay-sort"><option value="near" ${draft.sort!=='price'?'selected':''}>가까운 순</option><option value="price" ${draft.sort==='price'?'selected':''}>가격순</option></select></label></div><p class="note">${draft.flow==='course'?'전날 마지막·다음 날 첫 장소 기준의 이동 시간입니다.':'운영 중이며 선택 날짜 전체에 인원을 수용할 수 있는 샘플 객실입니다.'}</p><div class="grid">${arr.map(s=>`<article class="card"><div class="visual" aria-hidden="true">STAY</div><span class="pill">운영 중 · 연박 가능</span><h2>${esc(s.name)}</h2><p>${esc(draft.transport)} 기준 약 ${s.time}분 <span class="note">(샘플)</span></p><p>1박 ${money(s.price)}부터 / ${draft.nights}박 ${money(s.price*draft.nights)}부터</p>${btn('stay-detail','숙소 · 객실 보기','primary',`data-index="${s.id}"`)}</article>`).join('')}</div>`}
function detail(){if(!draft.stay)return guard('선택한 숙소가 없습니다. 숙소 목록에서 선택해주세요.','stays');const s=draft.stay;return hero('04　숙소 상세 · 객실 선택',esc(s.name),'체크인 15:00 · 체크아웃 11:00')+conditions()+`<div class="split" style="margin-top:25px"><section class="card"><div class="visual">STAY</div><h2>숙소 정보</h2><p>${esc(draft.region)} 소재 샘플 숙소 · 무료 Wi-Fi · 짐 보관</p><p class="note">위치와 사진은 실제 숙소 데이터 연동 시 표시됩니다.</p><h3>객실 선택</h3><form id="room-form">${[['스탠다드',2,0],['패밀리',4,40000]].map(([name,max,add])=>`<label class="card" style="padding:15px;margin:12px 0"><input type="radio" name="room" value="${name}" ${draft.guests>max?'disabled':''} ${draft.room?.name===name?'checked':''} required> ${name} · 최대 ${max}명 <br><span class="muted">1박 ${money(s.price+add)} / ${draft.nights}박 ${money((s.price+add)*draft.nights)}</span>${draft.guests>max?'<p class="warning">선택 인원 수용 불가</p>':''}</label>`).join('')}<button class="primary">${draft.flow==='course'?'보정한 코스로 예약 진행':'이 숙소 기준으로 AI 코스 만들기'}</button></form><div class="actions">${link('stays','다른 숙소 선택')}${draft.flow==='stay'?btn('without-course','코스 없이 예약 후 생성','text-button'):''}</div></section><aside class="card"><span class="pill">${draft.flow==='course'?'숙소 기준 일정 보정':'숙소 기준 코스 생성'}</span><h2>${draft.flow==='course'?esc(draft.selected?.name):'숙소에서 시작하는 여행'}</h2>${draft.flow==='course'?`<p class="note">원래 선택한 코스의 장소는 유지하고, 체크인·체크아웃과 ${esc(draft.transport)} 이동 시간에 맞춰 시각·순서를 조정합니다. 숙소를 바꾸면 원본 코스에서 다시 보정합니다.</p><p class="note">숙소 ↔ 일정 첫·마지막 장소: 약 ${s.time}분 (샘플)</p>${timeline(draft.selected,true)}`:'<p>숙소 위치, 객실, 숙박 일수와 체크인·체크아웃 시각을 반영한 코스를 생성합니다.</p>'}</aside></div>`}
function total(){return (draft.room?.price||0)*draft.nights}
function orderSummary(b=null){const v=b||{...draft,stay:draft.stay?.name,room:draft.room?.name,price:total()};return `<dl><dt>지역</dt><dd>${esc(v.region)}</dd><dt>숙소 · 객실</dt><dd>${esc(v.stay)} · ${esc(v.room)}</dd><dt>체크인</dt><dd>${esc(v.date)} 15:00</dd><dt>체크아웃</dt><dd>${endDate(v.date,v.nights)} 11:00</dd><dt>인원</dt><dd>${v.guests}명 · ${esc(v.companion)}</dd><dt>교통수단</dt><dd>${esc(v.transport)}</dd><dt>총 금액</dt><dd>${money(v.price)}</dd></dl>`}
function endDate(date,n){const d=new Date(date+'T12:00:00');d.setDate(d.getDate()+Number(n));return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function payment(){if(!draft.room||!draft.date||!draft.guests)return guard('예약할 객실과 여행 날짜·인원을 먼저 확인해주세요.','stays');return hero('05　예약 요청 · 결제','확인 한 번 더, <em>여행은 가볍게.</em>','연결된 코스는 결제 성공 후 내 코스 버전 1로 저장됩니다.')+`<div class="split"><section class="card"><h2>예약 정보</h2>${orderSummary()}<hr><h3>연결 코스</h3><p>${draft.selected?esc(draft.selected.name)+(draft.flow==='course'?' · 숙소 보정본':' · 숙소 기준 생성본'):'연결된 코스 없음 · 예약 후 생성 가능'}</p><p class="note">취소·환불 규정은 정책 확정이 필요합니다. 현재는 실제 결제 없는 시뮬레이션입니다.</p></section><section class="card"><h2>예약주문 · 결제대기</h2><p>객실 임시 점유 남은 시간</p><p id="hold-timer" class="hold"></p><label>결제 결과 테스트<select id="pay-result">${opts(['성공','실패','취소','점유 만료','중복 예약'],'성공')}</select></label><label class="checkline"><input type="checkbox" id="payment-agree"> 샘플 예약 정보와 결제 안내를 확인했습니다.</label><div class="actions">${btn('pay','샘플 결제 진행')}${btn('rehold','예약 요청 다시 시도','secondary')}</div><p class="note">실패·취소·만료 시 임시 점유를 해제합니다. 실서비스의 PG 웹훅·멱등 처리·중복 검증은 서버 연동이 필요합니다.</p></section></div>`}
function complete(){const b=state.bookings.find(b=>b.id===state.last);if(!b)return guard('완료된 새 예약이 없습니다.');return hero('06　예약 완료','여행 준비, <em>완료했어요.</em>','예약 상세와 연결된 코스는 마이페이지에서 다시 확인하세요.')+`<section class="card"><span class="pill">예약확정 · 샘플</span><h2>${esc(b.stay)}</h2>${orderSummary(b)}<div class="tip">${b.versions.length?'숙소에 연결된 코스를 버전 1로 저장했습니다.':'예약은 확정됐으며, 코스는 예약 후 생성할 수 있습니다.'}</div><div class="actions">${link('reservations','내 예약 보기','primary')}${link('courses','내 코스 보기')}${link('start','새 여행 시작')}</div></section>`}
function mypage(){let active=state.bookings.filter(b=>b.status!=='취소'&&!b.cancelRequested);return hero('MY TRAVEL','나의 여행, <em>한곳에서.</em>','예약부터 여행 일정, 직접 남긴 이야기까지.')+`<section class="card row"><div><span class="pill">샘플 사용자</span><h2>홍길동님, 안녕하세요.</h2><p class="muted">다음 여행도 나만의 취향으로 채워보세요.</p></div>${link('start','새 여행 만들기　→','primary')}</section><div class="grid three" style="margin-top:23px">${[['reservations','예약 내역',state.bookings.length,'예약 상태와 결제·환불 내역'],['courses','저장된 코스',active.filter(b=>b.versions.length).length,'예약에 연결된 확정 코스와 변경 이력'],['posts','내 휴먼 추천 코스',state.bookings.filter(b=>b.post).length,'내가 작성한 여행 기록과 최종 코스']].map(([p,title,count,desc])=>`<section class="card"><span class="pill">MY TRAVEL</span><h2>${title}</h2><p class="stats">${count}<span class="note"> 건</span></p><p class="muted">${desc}</p><div class="actions">${link(p,'자세히 보기　→','text-button')}</div></section>`).join('')}</div><section class="card" style="margin-top:23px"><h2>알림 설정</h2><label class="checkline"><input id="notify" type="checkbox" ${state.notify?'checked':''}> 여행 전 일정과 체크아웃 후 코스 작성 요청 알림 받기</label><p class="note">수신 거부 시 알림 대상에서 제외되며, 예약 취소 시 해당 예약의 예정 알림도 취소됩니다.</p></section>`}
function cancellable(b){return b.status==='예약확정'&&Date.now()<new Date(b.date+'T15:00:00').getTime()}
function reservations(){return hero('MY RESERVATIONS','기다리는 여행과 <em>지난 여행.</em>','예약 상태를 확인하고 상세 내역을 살펴보세요.')+`<div class="stack">${state.bookings.map(b=>`<section class="card"><div class="row"><div><span class="pill">${esc(b.status)}</span><h2>${esc(b.stay)}</h2><p class="muted">${esc(b.date)} ~ ${endDate(b.date,b.nights)} · ${b.guests}명</p></div><strong>${money(b.price)}</strong></div><details><summary>예약 상세</summary>${orderSummary(b)}<p>${b.status==='취소'?'연결 코스 비활성화 · 작성 자격 해제 · 예정 알림 취소':b.status==='환불실패'?'환불 실패 · 관리자 확인 및 재시도가 필요합니다.':b.status==='환불처리중'?'환불 처리 중입니다. 완료되면 취소 상태로 변경됩니다.':'예약에 연결된 코스는 내 코스에서 확인할 수 있습니다.'}</p></details><div class="actions">${link('courses','연결 코스 확인')}${cancellable(b)?btn('cancel','예약 취소 안내','secondary',`data-id="${b.id}"`):''}${b.status==='숙박완료'?link('posts',b.post?'작성한 코스 수정':'휴먼 추천 코스 작성'):''}</div><div id="cancel-${b.id}" hidden><hr><h3>예약 취소</h3><p>취소 수수료·환불 규정은 정책 확정이 필요합니다.</p><p class="note">취소 시 객실 점유를 해제하고 코스를 비활성화하며, 작성 자격과 예정된 알림을 해제합니다.</p><label>환불 결과 테스트<select id="refund-${b.id}">${opts(['환불처리중','취소','환불실패'],'환불처리중')}</select></label>${btn('confirm-cancel','취소 요청 확인','primary',`data-id="${b.id}"`)}</div></section>`).join('')}</div>`}
function myCourses(){return hero('MY COURSES','일정은 편하게, <em>변경은 신중하게.</em>','확정된 예약의 코스를 확인하고 변경안을 승인하세요.')+`<div class="stack">${state.bookings.map(b=>{const inactive=b.status==='취소'||b.cancelRequested;return `<section class="card"><span class="pill">${inactive?'비활성':b.versions.length?'저장됨':'생성 대기'}</span><h2>${esc(b.stay)} 여행 코스</h2><p class="muted">${esc(b.date)} ~ ${endDate(b.date,b.nights)}</p>${b.versions.length?`<details open><summary>현재 일정 · 버전 ${b.versions.at(-1).v}</summary>${timeline(b.versions.at(-1),true,b)}<p class="note">체크인 15:00 · 체크아웃 11:00 기준의 샘플 일정입니다.</p></details><details><summary>버전별 변경 이력</summary>${b.versions.map(v=>`<div class="version"><strong>버전 ${v.v} · ${esc(v.name)}</strong><p>${esc(v.note)}</p><p class="note">${esc(v.time)}</p></div>`).join('')}</details>`:'<p>연결된 코스가 없습니다. 예약은 유지한 채 코스를 생성할 수 있습니다.</p>'}${inactive?'<p class="warning">취소 요청된 예약의 코스는 변경·작성에 사용할 수 없습니다.</p>':!b.versions.length?btn('later-course','예약 후 코스 생성','primary',`data-id="${b.id}"`):`<details><summary>AI 코스 추천 · 변경 요청</summary><label>어떤 일정을 바꿀까요?<textarea id="request-${b.id}" placeholder="예: 비가 와서 실내 장소로 변경하고 싶어요"></textarea></label><label class="checkline"><input type="checkbox" id="location-${b.id}"> 현재 위치 사용 동의</label><p class="note">동의 시 현재 위치·날씨를, 거부 시 코스 지역 날씨를 사용하는 흐름입니다. 샘플에서는 실제 위치를 수집하지 않습니다.</p><div class="actions">${btn('change-course','변경안 만들기','primary',`data-id="${b.id}"`)}${btn('change-fail','응답 실패 상황','secondary')}</div><div id="proposal-${b.id}"></div></details>`}</section>`}).join('')}</div>`}
function posts(){return hero('MY HUMAN COURSES','다녀온 여행을 <em>이야기로.</em>','숙박완료 예약 한 건에 하나의 코스를 작성하고 수정할 수 있어요.')+`<div class="stack">${state.bookings.filter(b=>b.post||b.status==='숙박완료').map(b=>`<section class="card"><span class="pill">${b.post?'작성한 코스':'작성 가능'}</span><h2>${esc(b.post?.title||b.stay+' 여행 기록')}</h2><p class="muted">${esc(b.region)} · ${esc(b.date)} · ${esc(b.companion)}</p>${b.post?`<p class="chat-text">${esc(b.post.body)}</p>${b.post.photo?`<img class="photo-preview" alt="첨부한 여행 사진" src="${esc(b.post.photo)}">`:''}<details><summary>첨부된 최종 코스 · 버전 ${b.post.version}</summary>${timeline(b.versions.find(v=>v.v===b.post.version),true,b)}</details>`:''}${b.status==='숙박완료'&&b.versions.length?`<details><summary>${b.post?'작성 코스 수정':'휴먼 추천 코스 작성'}</summary><form data-post="${b.id}"><label>제목<input name="title" required maxlength="100" value="${esc(b.post?.title||'')}"></label><label>여행 이야기<textarea name="body" required>${esc(b.post?.body||'')}</textarea></label><label>여행 사진 <span class="note">(선택)</span><input name="photo" type="file" accept="image/png,image/jpeg,image/webp"></label><p class="note">최종 저장 코스 버전 ${b.versions.at(-1).v}를 첨부합니다. 사진은 1MB 이하의 샘플 파일을 사용해주세요.</p><button class="primary" type="submit">${b.post?'수정 내용 저장':'코스 공유하기'}</button></form></details>`:!b.versions.length?`<p>먼저 예약에 연결된 코스를 생성해주세요.</p>${link('courses','내 코스로 이동')}`:'<p class="warning">취소된 예약은 작성·수정할 수 없습니다.</p>'}</section>`).join('')||'<div class="empty">숙박완료 예약 또는 작성한 코스가 없습니다.</div>'}</div>`}
