function parseChat(e){e.preventDefault();const text=new FormData(e.target).get('chat');const aliases=[['부산','부산광역시'],['서귀포','제주 서귀포시'],['제주','제주 제주시'],['강릉','강원 강릉시'],['서울','서울특별시']];let region=aliases.find(([k])=>text.includes(k))?.[1];if(text.includes('광주'))region=text.includes('경기')?'경기 광주시':text.includes('광역')?'광주광역시':null;let n=text.match(/(\d+)박\s*(\d+)일/),nights=text.includes('당일')?0:n?+n[1]:null;if(nights!==null&&nights>3){msg('샘플에서는 당일부터 3박 4일까지 지원합니다. 조건 선택에서 확인해주세요.',true);return}if(!region||nights===null){if(text.includes('광주')&&!region){draft.region='광주광역시';draft.nights=nights??1;$('#extracted').hidden=false;$('#chat-result').textContent='광주는 광주광역시와 경기 광주시 후보가 있습니다. 지역 후보와 여행 기간을 확인해주세요.';$('#confirm-chat').innerHTML=fields()+`<button class="primary">확인 · AI 코스 만들기</button>`;$('#extracted').scrollIntoView();return}msg(!region&&!/여행|박|당일|코스/.test(text)?'여행·코스에 관련된 요청을 입력해주세요.':!region?'지원 지역을 알려주세요: 부산, 제주, 강릉, 서울, 광주. 지역이 없다면 조건 선택 방식을 이용해주세요.':'여행 기간을 알려주세요. 예: 당일 또는 1박 2일',true);return}const dt=text.match(/(\d{4})[-.](\d{1,2})[-.](\d{1,2})/);draft={region,nights,companion:['친구','연인','가족'].find(k=>text.includes(k))||(text.includes('혼자')?'혼자':'친구'),transport:/자가용|자동차/.test(text)?'자가용':'대중교통',date:dt?`${dt[1]}-${dt[2].padStart(2,'0')}-${dt[3].padStart(2,'0')}`:'',guests:text.match(/(\d+)명/)?+text.match(/(\d+)명/)[1]:null};$('#extracted').hidden=false;$('#chat-result').textContent='문장에서 찾은 샘플 조건입니다. 동행·교통수단의 기본값을 포함하므로 확인·수정 후 진행해주세요.';$('#confirm-chat').innerHTML=fields()+`<button class="primary">확인 · AI 코스 만들기</button>`;save();$('#extracted').scrollIntoView({behavior:'smooth'})}
