function timer(){clearInterval(tick);if(!$('#hold-timer'))return;if(!draft.hold)beginHold();const update=()=>{let n=Math.max(0,Math.floor((draft.hold-Date.now())/1000));$('#hold-timer').textContent=`${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;document.querySelector('[data-action="pay"]').disabled=n===0;if(n===0)$('#hold-timer').textContent='점유 만료 · 다시 요청해주세요'};update();tick=setInterval(update,1000)}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id,booking=state.bookings.find(v=>v.id===id);if(a==='stay-first'){const f=$('#condition-form');if(!f.reportValidity())return;readForm(f);draft.flow=draft.nights===0?'course':'stay';go(draft.nights===0?'candidates':'stays')}if(a==='chat-fail'){$('#condition-form').scrollIntoView({behavior:'smooth'});msg('응답이 지연되거나 실패할 경우 조건 선택으로 여행 조건을 확인해 진행하세요.')}if(a==='generate'){draft.candidates=['바다·산책과 여유','문화·전시와 골목','맛집·카페와 쉼'].map((name,i)=>({name,places:[...getPlaces().slice(i),...getPlaces().slice(0,i)]}));save();$('#course-results').innerHTML=candidateCards()}if(a==='generation-fail'){delete draft.candidates;delete draft.selected;save();$('#course-results').innerHTML=`<div class="message">코스 생성 실패 · 코스는 예약 후 만들 수 있습니다.</div><div class="actions">${btn('generate','다시 시도')}${draft.flow==='stay'?btn('without-course','코스 없이 예약 진행','secondary'):btn('regional','숙소 먼저 고르기','secondary')}</div>`}if(a==='select-course'){draft.selected=structuredClone(draft.candidates[+b.dataset.index]);if(draft.flow==='stay'){beginHold();go('payment')}else go('stays')}if(a==='regional'){draft.flow='stay';delete draft.selected;delete draft.stay;delete draft.room;go('stays')}if(a==='expand')msg('추천 범위를 확대했지만 수용 가능한 샘플 객실이 없습니다. 인원·날짜를 변경하거나 지역 숙소 목록을 확인해주세요.');if(a==='stay-detail'){const i=+b.dataset.index;draft.stay={name:draft.region+(i?' 어반 호텔':' 가든 스테이'),price:i?95000:110000,time:draft.transport==='자가용'?(i?19:12):(i?31:22)};delete draft.room;delete draft.hold;go('detail')}if(a==='without-course'){if(!draft.room){msg('먼저 객실을 선택하고 코스 만들기로 진행한 후, 생성 실패 화면에서 코스 없이 예약할 수 있습니다.',true);return}delete draft.selected;beginHold();go('payment')}if(a==='rehold'){beginHold();timer();msg('예약주문을 다시 요청해 객실을 임시 점유했습니다. (샘플)')}if(a==='pay'){if(!$('#payment-agree').checked){msg('결제 안내 확인에 체크해주세요.',true);return}if(Date.now()>=draft.hold){msg('임시 점유가 만료되었습니다. 다시 요청해주세요.',true);return}const