|p.base!==booking.versions.at(-1).v){msg('변경안이 만료되었습니다. 새로 요청해주세요.',true);return}if(booking.cancelRequested||booking.status==='취소')return;booking.versions.push({name:booking.versions.at(-1).name,v:p.base+1,places:['숙소 주변 아침 산책','실내 전시관 방문 · 이동 약 15분','지역 식당 · 숙소 복귀'],note:p.request,time:today()});delete booking.proposal;save();render();msg('승인한 변경안을 새 버전으로 저장했습니다. 이전 이력은 유지됩니다.')}if(a==='reject'){delete booking.proposal;save();$(`#proposal-${id}`).textContent='변경안을 폐기했습니다. 기존 코스가 유지됩니다.'}});
