        result.put("ownerProfile",owner);
        result.put("suspensions",data.suspensions(id));
        result.put("ownerReviews",owner==null?List.of():data.reviewHistory(owner.getOwnerId()));
        result.put("ownerLodgings",owner==null?List.of():data.lodgings().stream()
            .filter(x -> Objects.equals(owner.getOwnerId(),x.getOwnerId())).toList());
        return result;
