import { useState } from 'react';

const navigation = [
  { label: '여행 시작', href: '#/' },
  { label: '코스추천', href: '#/ai-course' },
  { label: '조건검색', href: '#/conditions' },
  { label: '숙소 찾기', href: '#/stays' },
  { label: '내 여행 일정', href: '#/my-courses' },
  { label: '휴먼 추천 코스', href: '#/human-courses' },
  { label: '마이페이지', href: '#/mypage' },
];

export default function Header({ route, onUnavailable, member, onLogout, loggingOut }) {
  const [menuOpen, setMenuOpen] = useState(false);
  const link = (item) => item.href ? (
    <a key={item.label} href={item.href} aria-current={route === item.href.slice(1) ? 'page' : undefined} onClick={() => setMenuOpen(false)}>{item.label}</a>
  ) : (
    <button key={item.label} type="button" className="nav-link" onClick={() => { setMenuOpen(false); onUnavailable(item.label); }}>{item.label}</button>
  );
  return <header className="site-header">
    <div className="header-inner">
      <div className="brand-wrap">
        <button className="menu-toggle" type="button" aria-label={menuOpen ? '메뉴 닫기' : '메뉴 열기'} aria-expanded={menuOpen} aria-controls="mobile-menu" onClick={() => setMenuOpen(!menuOpen)}>
          <span></span><span></span><span></span>
        </button>
        <a className="brand" href="#/">smart <span>travel</span></a>
      </div>
      <nav className="desktop-nav" aria-label="주 메뉴">{navigation.map(link)}{member ? <span className="auth-account"><span className="auth-account__name">{member.nickname || member.loginId}님</span><button className="account" type="button" disabled={loggingOut} onClick={() => { setMenuOpen(false); onLogout(); }}>{loggingOut ? '로그아웃 중…' : '로그아웃'}</button></span> : <a className="account" href="#/login" aria-current={route === '/login' ? 'page' : undefined}>로그인</a>}</nav>
    </div>
    {menuOpen && <nav id="mobile-menu" className="menu-panel" aria-label="전체 메뉴">{navigation.map(link)}{member ? <span className="auth-account"><span className="auth-account__name">{member.nickname || member.loginId}님</span><button className="account" type="button" disabled={loggingOut} onClick={() => { setMenuOpen(false); onLogout(); }}>{loggingOut ? '로그아웃 중…' : '로그아웃'}</button></span> : <a className="nav-link" href="#/login" aria-current={route === '/login' ? 'page' : undefined} onClick={() => setMenuOpen(false)}>로그인</a>}</nav>}
  </header>;
}

base.frontend/src/components/layout/MainLayou:
.main-page{min-height:100vh;display:flex;flex-direction:column;background:radial-gradient(ellipse at 85% 50%,#f4faf7 0,transparent 47%)}

.mp-topbar{position:relative;z-index:21;background:rgba(255,255,255,.92);min-height:64px;padding:0 24px;display:flex;justify-content:space-between;align-items:center;gap:20px;border-bottom:1px solid #edf2ef}
.mp-topbar-left{display:flex;align-items:center;gap:18px}
.mp-brand{font-size:24px;font-weight:800;letter-spacing:-1.2px;white-space:nowrap}
.mp-brand span{color:#09836d}
.mp-menu-toggle{display:flex;flex-direction:column;justify-content:center;gap:5px;width:26px;height:36px;padding:0;border:0;background:none}
.mp-menu-toggle span{display:block;width:18px;height:2px;background:#263c44;border-radius:2px}
.mp-account{border:1px solid #dbe3e8;border-radius:9px;background:#fff;padding:10px 21px;color:#263a43}

.mp-global-notice{display:flex;align-items:center;justify-content:space-between;gap:14px;margin:14px 24px 0;padding:12px 18px;background:#eef8f3;border:1px solid #cde7da;border-radius:10px;color:#285e4c;font-size:13px}
.mp-global-notice button{border:0;background:none;color:inherit;font-size:17px;line-height:1;padding:0}

.mp-body{flex:1;display:flex;min-height:0}

.mp-sidebar{width:256px;flex:0 0 auto;background:#fff;border-right:1px solid #edf2ef;overflow:hidden;transition:width .2s ease}
.mp-sidebar-closed{width:0;border-right-color:transparent}
.mp-sidebar-inner{width:256px;height:100%;display:flex;flex-direction:column;padding:20px 16px;box-sizing:border-box}
.mp-new-trip{display:flex;align-items:center;gap:9px;border:1px solid #0c806b;background:#0c806b;color:#fff;padding:13px 16px;border-radius:11px;font-size:14px;font-weight:700;white-space:nowrap}
.mp-new-trip:hover{background:#076d5b}
.mp-sidebar-nav{display:flex;flex-direction:column;gap:2px;margin-top:18px}
.mp-sidebar-item{display:block}
.mp-sidebar-link{display:flex;align-items:center;gap:10px;width:100%;padding:11px 12px;border:0;border-radius:9px;background:none;color:#324542;font-size:14px;text-align:left;white-space:nowrap}
.mp-sidebar-link:hover,.mp-sidebar-link[aria-expanded=true]{background:#f0f8f4;color:#09836d}
.mp-sidebar-submenu{display:flex;flex-direction:column;gap:2px;margin:2px 0 6px 34px}
.mp-sidebar-submenu button,.mp-sidebar-submenu a{border:0;background:none;padding:8px 10px;border-radius:7px;color:#6b7c76;font-size:13px;text-align:left;white-space:nowrap;text-decoration:none}
.mp-sidebar-submenu button:hover,.mp-sidebar-submenu a:hover{background:#f0f8f4;color:#09836d}
.mp-sidebar-bottom{margin-top:auto;padding-top:14px;border-top:1px solid #edf2ef}

.mp-content{flex:1;min-width:0;display:flex;flex-direction:column}

.mp-main{width:100%;max-width:1320px;flex:1;margin:0 auto;padding:54px 48px 50px}

.mp-footer{min-height:78px;border-top:1px solid #edf2ef;display:flex;flex-direction:column;justify-content:center;align-items:center;gap:6px;padding:16px 0;color:#889c95;font-size:13px}
.mp-footer nav{display:flex;align-items:center}
.mp-footer-item{display:flex;align-items:center}
.mp-footer a{color:#5c6f68;font-weight:600}
.mp-footer a:hover{color:#09836d}
.mp-footer-sep{margin:0 14px;color:#d3ddd8}
.mp-footer-fine{margin:0;color:#b3bfba;font-size:11px}

@media(max-width:900px){
  .mp-main{padding:40px 28px 40px}
}
@media(max-width:700px){
  .mp-topbar{min-height:56px;padding:0 16px}
  .mp-brand{font-size:21px}
  .mp-body{position:relative}
  .mp-sidebar{position:fixed;top:56px;left:0;bottom:0;width:240px;transform:translateX(-100%);transition:transform .22s ease;z-index:40;box-shadow:0 18px 45px rgba(20,40,30,.18);border-right:1px solid #edf2ef}
  .mp-sidebar:not(.mp-sidebar-closed){transform:translateX(0)}
  .mp-sidebar-closed{width:240px}
  .mp-sidebar-inner{width:240px}
  .mp-main{padding:34px 20px 36px}
  .mp-footer{min-height:auto}
}

