/* Smart Travel 공유 디자인 (기준 그림: 18 Lavender Gray & Aqua)
   - 모든 이름이 st- 로 시작해서 각자 페이지의 CSS와 겹치지 않습니다.
   - 페이지 맨 바깥 태그에 class="st-page" 를 붙이면 그 안에만 적용됩니다. */

@font-face { font-family: 'ST Pretendard'; src: url('https://cdn.jsdelivr.net/gh/orioncactus/pretendard@v1.3.9/packages/pretendard/dist/web/static/woff2/Pretendard-Regular.woff2') format('woff2'); font-weight: 400; font-display: swap; }
@font-face { font-family: 'ST Pretendard'; src: url('https://cdn.jsdelivr.net/gh/orioncactus/pretendard@v1.3.9/packages/pretendard/dist/web/static/woff2/Pretendard-Bold.woff2') format('woff2'); font-weight: 700; font-display: swap; }
@font-face { font-family: 'ST SUIT'; src: url('https://cdn.jsdelivr.net/gh/sun-typeface/SUIT@2.0.5/fonts/static/woff2/SUIT-Heavy.woff2') format('woff2'); font-weight: 900; font-display: swap; }

:root {
  /* 색: 페이지에서는 이 변수만 씁니다 */
  --st-bg: #E6E5EE;          /* 페이지 바탕 */
  --st-aqua: #A3CECA;        /* 버튼·카드 바탕 (글자색으로 쓰지 않기) */
  --st-aqua-hover: #8FC2BD;
  --st-title: #478A88;       /* 큰 제목 전용 (24px 이상) */
  --st-teal: #2F6F6D;        /* 작은 강조 글자·아이콘·테두리 */
  --st-ink: #2C2C4C;         /* 본문 글자 */
  --st-muted: #4A4A68;       /* 보조 글자 */
  --st-surface: #FAFAFD;     /* 입력창·흰 카드 */
  --st-line: #CFCEDC;        /* 옅은 선 */
  --st-danger: #A83B4B;      /* 오류 */

  /* 글꼴 */
  --st-font-title: 'ST SUIT', 'ST Pretendard', 'Malgun Gothic', 'Apple SD Gothic Neo', sans-serif;
  --st-font-body: 'ST Pretendard', 'Malgun Gothic', 'Apple SD Gothic Neo', sans-serif;

  /* 모양 */
  --st-radius-s: 12px;
  --st-radius-m: 16px;
  --st-radius-pill: 999px;
  --st-shadow: 0 6px 20px rgba(44, 44, 76, .08);
  --st-width: 1320px;
}

/* 페이지 틀 */
.st-page {
  min-height: 100vh;
  background: var(--st-bg);
  color: var(--st-ink);
  font-family: var(--st-font-body);
  font-size: 16px;
  line-height: 1.6;
  word-break: keep-all;
}
.st-page *, .st-page *::before, .st-page *::after { box-sizing: border-box; }
:where(.st-page) a { color: inherit; text-decoration: none; }
.st-page :focus-visible { outline: 3px solid var(--st-teal); outline-offset: 2px; }
.st-container { max-width: var(--st-width); margin: 0 auto; padding: 0 48px; }

/* 상단 메뉴 */
.st-header { border-bottom: 1px solid var(--st-line); }
.st-header-inner { max-width: var(--st-width); min-height: 66px; margin: 0 auto; padding: 0 48px; display: flex; align-items: center; justify-content: space-between; gap: 24px; }
.st-logo { display: inline-flex; align-items: center; gap: 12px; color: var(--st-title); font-family: var(--st-font-title); font-weight: 900; font-size: 28px; white-space: nowrap; }
.st-logo svg { width: 48px; height: 32px; }
.st-nav { display: flex; align-items: center; gap: 32px; color: var(--st-muted); font-weight: 700; }
.st-nav a:hover, .st-nav a[aria-current="page"] { color: var(--st-teal); }

/* 제목 */
.st-hero { text-align: center; padding: 28px 0 8px; }
.st-eyebrow { margin: 0 0 8px; color: var(--st-ink); font-weight: 700; font-size: 20px; }
.st-title { margin: 0; color: var(--st-title); font-family: var(--st-font-title); font-weight: 900; font-size: clamp(44px, 6vw, 88px); line-height: 1.08; letter-spacing: -.02em; }
.st-lead { margin: 14px 0 0; color: var(--st-ink); font-weight: 700; font-size: 24px; }
.st-h2 { margin: 0; color: var(--st-title); font-family: var(--st-font-title); font-weight: 900; font-size: clamp(30px, 3.6vw, 48px); line-height: 1.15; letter-spacing: -.01em; }
.st-section-head { display: flex; align-items: center; justify-content: space-between; gap: 20px; margin: 32px 0 18px; }
.st-note { color: var(--st-muted); font-size: 14px; }

/* 버튼 */
.st-btn { display: inline-flex; align-items: center; justify-content: center; gap: 12px; min-height: 44px; padding: 8px 28px; border: 0; border-radius: var(--st-radius-s); background: var(--st-aqua); color: var(--st-ink); font-family: var(--st-font-body); font-weight: 700; font-size: 18px; cursor: pointer; }
.st-btn:hover { background: var(--st-aqua-hover); }
.st-btn:disabled { opacity: .5; cursor: not-allowed; }
.st-btn-lg { min-height: 58px; padding: 10px 36px; font-family: var(--st-font-title); font-weight: 900; font-size: 22px; }
.st-btn-line { background: transparent; border: 2px solid var(--st-teal); color: var(--st-teal); }
.st-btn-line:hover { background: rgba(163, 206, 202, .3); }
.st-link { display: inline-flex; align-items: center; gap: 10px; color: var(--st-ink); font-weight: 700; }
.st-link:hover { color: var(--st-teal); }

/* 칩 버튼 */
.st-chips { display: flex; flex-wrap: wrap; justify-content: center; gap: 12px; }
