export default function AiCoursePage() {
  const [message, setMessage] = useState('');
  const [notice, setNotice] = useState('');

  function startConversation() {
    if (!message.trim()) {
      setNotice('여행 이야기를 입력해 주세요.');
      return;
    }
    setNotice('입력한 여행 이야기는 유지됩니다. 대화 추천 기능은 연결 준비 중입니다.');
