import CourseForm from '../components/CourseForm';
import '../human-course.css';
import CoursePlan from '../components/CoursePlan';
import PageHeading from '../components/PageHeading';
import { previewCourses, previewReservations } from '../data/previewData';
import { useState } from 'react';
import { creationError, finalCourse } from '../data/courseState';

const names = { COMPLETED: '숙박 완료', CANCELED: '취소된 예약', UPCOMING: '숙박 예정', CONFIRMED: '예약 확정 / 숙박완료 전환 전' };

export default function HumanCourseCreate({ reservations = previewReservations, courses = previewCourses, execute }) {
  const [selectedId, setSelectedId] = useState('');
  const [loadedId, setLoadedId] = useState('');
  const [notice, setNotice] = useState('');
  const selected = reservations.find((reservation) => reservation.id === loadedId);
  const final = finalCourse(selected);
  function submit(fields) {
    const result = execute?.({ type: 'create', reservationId: loadedId, fields });
    if (result?.error) setNotice(result.error);
    else if (result?.id) window.location.hash = `/human-courses/${result.id}`;
  }
  return <div className="human-courses"><div className="page">
    <PageHeading breadcrumb="코스 작성" title="여행 코스 공유하기" description="숙박 완료 예약에 연결된 확정 일정을 불러와서 후기를 등록합니다."><a className="button" href="#/human-courses">← 목록으로</a></PageHeading>
    <div className="step-row" aria-label="작성 단계"><div className="step"><strong>1</strong> 예약 선택</div><span className="step-arrow">→</span><div className="step"><strong>2</strong> 최종 일정 확인</div><span className="step-arrow">→</span><div className="step"><strong>3</strong> 후기 작성</div></div>
    <div className="layout wide-left"><div>
      <section className="panel"><div className="panel-heading"><h2>1. 숙박 완료 예약 선택</h2><span className="helper">가상 예약 데이터</span></div><p className="form-help">체크아웃 시각이 지나 숙박 완료로 전환된 예약만 작성할 수 있습니다. 예약 1건당 1회 작성하며 이후에는 기존 글을 수정합니다.</p>
        <details className="mock-tools"><summary>작성 자격 배치 시연</summary><p>R106은 체크아웃 후 배치 전, R107은 기준 시각에 체크아웃 전입니다.</p><button onClick={() => { const result = execute?.({ type: 'batch' }); setNotice(`${result?.count || 0}건을 숙박 완료로 전환했습니다.`); setLoadedId(''); }}>12:00 숙박완료 배치 실행 (샘플)</button></details>
        <div className="reservation-list" role="group" aria-label="내 예약 목록">{reservations.map((reservation) => {
          const message = creationError({ courses }, reservation);
          return <div className={`reservation-option${message ? ' is-disabled' : ''}`} key={reservation.id}><div className="reservation-top"><label className="reservation-label"><input type="radio" name="reservation" value={reservation.id} checked={selectedId === reservation.id} onChange={() => { setSelectedId(reservation.id); setLoadedId(''); setNotice(''); }} disabled={Boolean(message)} /><span>{reservation.id} | {reservation.name} | {reservation.dates}</span></label><span className={`badge${message ? ' badge-disabled' : ''}`}>{names[reservation.status] || reservation.status}</span></div><p className="reservation-reason">{message || '작성 가능'}</p><p className="helper">체크아웃 시각: {reservation.checkoutAt}</p>{courses.some((course) => course.mine && course.reservationId === reservation.id) && <a className="button" href={`#/human-courses/${courses.find((course) => course.mine && course.reservationId === reservation.id).id}/edit`}>이미 작성한 코스 수정하기 →</a>}</div>;
        })}{!reservations.length && <p className="empty-state">예약 내역이 없습니다.</p>}</div>
        <p><button className="primary" onClick={() => { const reservation = reservations.find((r) => r.id === selectedId); const error = creationError({ courses }, reservation); if (error) { setNotice(error); return; } setLoadedId(selectedId); setNotice(''); }}>선택한 예약의 최종 코스 불러오기</button></p>
        {notice && <p className="status" role="status">{notice}</p>}
      </section>
      <section className="panel"><div className="panel-heading"><h2>2. 최종 여행 코스 확인</h2><span className="badge">읽기 전용</span></div><p className="form-help">예약을 선택하고 최종 코스를 불러오세요. 첨부할 일정은 이 화면에서 수정할 수 없습니다.</p><CoursePlan plan={final?.plan} version={final?.version} /></section>
      <section className="panel"><h2>3. 사진 / 후기 작성</h2><CourseForm key={loadedId} disabled={!selected} onSubmit={submit} cancelHref="#/human-courses" /></section>
    </div><aside className="panel sidebar-hint"><h3>이 화면의 처리 흐름</h3><ol><li>숙박이 완료된 예약 선택</li><li>예약에 연결된 최종 코스 불러오기</li><li>코스 내용은 고정된 상태로 후기 입력</li><li>등록하면 상세 페이지로 이동</li></ol><p className="note">R101은 작성 가능, R102는 기존 게시글 수정 대상입니다.</p></aside></div>
  </div></div>;
}

import CourseActions from '../components/CourseActions';
import CourseComments from '../components/CourseComments';
import CoursePlan from '../components/CoursePlan';
import '../human-course.css';
import PageHeading from '../components/PageHeading';
import { previewCourses } from '../data/previewData';

export default function HumanCourseDetail({ courses = previewCourses, courseId = 1, execute }) {
  const course = courses.find((item) => String(item.id) === String(courseId));
  const blocked = course?.visibility === 'BLINDED';
  return <div className="human-courses"><div className="page">
    <PageHeading breadcrumb="코스 상세" title="코스 상세 보기" description="게시글 내용, 실제 방문 순서, 댓글과 좋아요를 확인합니다."><a className="button" href="#/human-courses">← 목록으로</a></PageHeading>
    {!course || blocked ? <section className="panel"><h2>{blocked ? '블라인드 처리된 코스입니다.' : '코스를 찾을 수 없습니다.'}</h2><p>{blocked ? '관리자 검토로 숨김 처리되어 게시글·사진·일정·댓글을 볼 수 없습니다.' : '존재하지 않는 코스입니다.'}</p>{course?.mine && <a className="button" href={`#/human-courses/${course.id}/edit`}>내 게시글 수정하기 (숨김 상태 유지)</a>}</section> : <>
      <div className="layout wide-left"><div>
        <article className="panel"><div className="article-intro"><p className="small-kicker">코스 정보</p><h2>{course.title}</h2><p className="course-meta">작성자: {course.author} | 지역: {course.region} | 여행 유형: {course.category} | 동행: {course.companion} | 작성일: {course.createdAt}</p><p className="summary">{course.summary}</p></div>
          <h3>등록 사진 <span className="helper">· 실제 이미지는 표시하지 않음</span></h3><ul className="photo-boxes">{(course.photos.length ? course.photos : ['첨부된 사진 없음']).map((photo, index) => <li key={index}>{photo}</li>)}</ul>
          <hr className="divider" /><h3>여행 후기</h3><p className="writing-sample">{course.body}</p>
        </article>
        <section className="panel"><div className="panel-heading"><h2>방문 코스 / 일정</h2></div><CoursePlan plan={course.plan} version={course.courseVersion} /></section>
      </div><aside>
        <CourseActions course={course} execute={execute} />
        <section className="panel sidebar-hint"><h3>상세 화면에서 확인할 것</h3><ol><li>일정과 후기 표시</li><li>좋아요 누르기 / 취소</li><li>게시글 신고</li><li>댓글 작성 및 삭제</li><li>내 게시글 수정 화면 이동</li></ol></section>
      </aside></div>
      <CourseComments course={course} execute={execute} />
    </>}
  </div></div>;
}

import { useState } from 'react';
import CourseForm from '../components/CourseForm';
import '../human-course.css';
import CoursePlan from '../components/CoursePlan';
import PageHeading from '../components/PageHeading';
import { previewCourses } from '../data/previewData';

export default function HumanCourseEdit({ courses = previewCourses, courseId = 2, execute }) {
  const [notice, setNotice] = useState('');
  function submit(fields) {
    const result = execute?.({ type: 'edit', id: courseId, fields });
    if (result?.error) setNotice(result.error);
    else if (result?.id) window.location.hash = `/human-courses/${result.id}`;
  }
  const course = courses.find((item) => String(item.id) === String(courseId));
  return <div className="human-courses"><div className="page">
    <PageHeading breadcrumb="작성 코스 수정" title="내 여행 코스 수정" description="게시글의 설명과 후기만 수정합니다. 원래 여행 일정은 수정되지 않습니다."><a className="button" href={course ? `#/human-courses/${course.id}` : '#/human-courses'}>← {course ? '상세로 돌아가기' : '목록으로'}</a></PageHeading>
    {notice && <p className="status" role="status">{notice}</p>}
    {!course?.mine ? <section className="panel"><h2>수정할 수 없습니다</h2><p>{course ? '다른 사람의 코스는 수정할 수 없습니다.' : '해당 코스를 찾지 못했습니다.'}</p></section> : <div className="layout wide-left">
      <section className="panel"><div className="panel-heading"><h2>기존 코스 정보 수정</h2><span className="badge">내 게시글</span></div><p className="note">게시글 ID: {course.id} | 연결 예약: {course.reservationId || '없음(샘플)'} | 최종 코스 v{course.courseVersion}</p>{course.visibility === 'BLINDED' && <p className="note">블라인드 상태: 수정해도 자동 공개되지 않습니다.</p>}<CourseForm key={course.id} course={course} mode="edit" onSubmit={submit} cancelHref={`#/human-courses/${course.id}`} /></section>
      <aside><section className="panel"><div className="panel-heading"><h2>연결된 여행 일정</h2><span className="badge badge-neutral">수정 불가</span></div><p className="form-help">게시글을 수정해도 여행 일정과 연결 예약 정보는 그대로 유지됩니다.</p><CoursePlan plan={course.plan} version={course.courseVersion} /></section><section className="panel sidebar-hint"><h3>수정 흐름</h3><ol><li>기존 글을 입력란에 표시</li><li>제목 / 후기 / 사진명 변경</li><li>기존 글 ID 그대로 유지</li><li>상세 페이지로 돌아가 확인</li></ol></section></aside>
    </div>}
  </div></div>;
}

import CourseCard from '../components/CourseCard';
import '../human-course.css';
import CourseFilters from '../components/CourseFilters';
import PageHeading from '../components/PageHeading';
import { previewCourses } from '../data/previewData';
import { useState } from 'react';
import { filterCourses } from '../data/courseState';

export default function HumanCourseList({ courses = previewCourses, execute }) {
  const [filters, setFilters] = useState({});
  const [resetting, setResetting] = useState(false);
  const visible = filterCourses(courses, filters);
  return <div className="human-courses"><div className="page">
    <PageHeading title="다른 여행자의 추천 코스" description="조건을 선택하고, 목록에서 코스를 눌러 상세 내용을 확인합니다."><a className="button button-primary" href="#/human-courses/create">+ 내 코스 작성</a></PageHeading>
    <div className="layout">
      <aside className="panel"><div className="panel-heading"><h2>검색 / 필터</h2></div><CourseFilters onSearch={setFilters} onReset={() => setFilters({})} /></aside>
      <section className="panel"><div className="panel-heading"><h2>공유 코스 <span className="muted">({visible.length}건)</span></h2><span className="helper">공유된 여행 코스</span></div>
        <div className="course-grid" aria-live="polite">{visible.length ? visible.map((course) => <CourseCard key={course.id} course={course} detailHref={`#/human-courses/${course.id}`} />) : <div className="empty-state">검색 결과가 없습니다. 다른 조건을 선택해 보세요.</div>}</div>
        <div className="footer-tools"><button onClick={() => setResetting(true)}>전체 샘플 데이터 초기화</button><a href="#/human-courses/moderation">신고·블라인드 상태 시연 →</a></div>
        {resetting && <div className="note"><p>작성한 글·댓글·좋아요 등 모든 시연 변경을 초기화할까요?</p><div className="actions"><button onClick={() => { execute?.({ type: 'reset' }); setResetting(false); }}>초기화 확인</button><button onClick={() => setResetting(false)}>취소</button></div></div>}
      </section>
    </div>
  </div></div>;
}

import PageHeading from '../components/PageHeading';
import '../human-course.css';
import { previewCourses } from '../data/previewData';

export default function HumanCourseModeration({ courses = previewCourses, execute }) {
  const reported = courses.filter((course) => course.reportedByMe || course.visibility === 'BLINDED');
  return <div className="human-courses"><div className="page">
    <PageHeading title="신고·블라인드 상태 시연" description="관리자 처리 결과를 확인하는 개발 검증 화면입니다."><a className="button" href="#/human-courses">← 코스 목록</a></PageHeading>
    <p className="note">실제 관리자 기능이나 권한 인증이 아닙니다. 신고 접수 자체는 게시글을 자동으로 숨기지 않습니다.</p>
