    String request(String body);
}

package com.smarttraveler.chat;

import org.springframework.beans.factory.annotation.Value;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Component;
import org.springframework.web.server.ResponseStatusException;
import tools.jackson.databind.JsonNode;
import tools.jackson.databind.ObjectMapper;
import tools.jackson.databind.node.ObjectNode;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.time.Duration;
import java.util.Map;
import java.util.List;

/** 파이썬 AI 서버와 통신한다. OpenAI 키는 이 서버에서 읽지 않는다. */
@Component
public class PythonAiClient {
    private final ObjectMapper mapper;
    private final URI endpoint;
    private final HttpClient client = HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(5)).build();
    public PythonAiClient(ObjectMapper mapper, @Value("${AI_SERVICE_URL:http://127.0.0.1:8001}") String baseUrl) {
        this.mapper = mapper;
        this.endpoint = URI.create(baseUrl.replaceAll("/+$", "") + "/internal/dialogue");
    }
    public record Result(String message, boolean confirmed) {}
    public Result process(String message, String previousQuestion, ObjectNode conditions, List<Map<String, Object>> candidates) {
        String body = mapper.writeValueAsString(Map.of("message", message, "previousQuestion", previousQuestion, "conditions", conditions, "candidates", candidates));
        HttpRequest request = HttpRequest.newBuilder(endpoint).timeout(Duration.ofSeconds(75))
                .header("Content-Type", "application/json").POST(HttpRequest.BodyPublishers.ofString(body)).build();
        try {
            HttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());
            if (response.statusCode() != 200) throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE, "AI 서버가 요청을 처리하지 못했습니다.");
            JsonNode parsed = mapper.readTree(response.body());
            JsonNode changes = parsed.path("changes"), question = parsed.path("question");
            if (!changes.isObject() || !question.isTextual() || question.asText().isBlank() || question.asText().length() > 3000)
                throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE, "AI 서버 응답 형식이 올바르지 않습니다.");
            ConditionMerger.merge(changes, conditions);
            return new Result(question.asText(), parsed.path("confirmed").asBoolean(false));
        } catch (InterruptedException ex) {
            Thread.currentThread().interrupt();
            throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE, "AI 서버 요청이 중단되었습니다.");
        } catch (java.io.IOException ex) {
            throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE, "AI 서버에 연결할 수 없습니다.");
        } catch (ResponseStatusException ex) { throw ex; }
        catch (RuntimeException ex) { throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE, "AI 서버 응답을 처리할 수 없습니다."); }
    }
}

package com.smarttraveler.chat;

import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Component;
import tools.jackson.databind.node.ObjectNode;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.*;
import java.util.regex.*;

/** AI 연결 전, 일부 명확한 표현만 알아보는 임시 예시 규칙이다. */
@Component
public class RuleBasedConditionExtractor implements ConditionExtractor {
    private final JdbcTemplate jdbc;
    public RuleBasedConditionExtractor(JdbcTemplate jdbc) { this.jdbc = jdbc; }
    private record Region(long id, String name) {}
    private static Matcher match(String pattern, String text) { return Pattern.compile(pattern).matcher(text); }
    private static void number(ObjectNode values, String key, Matcher found, int min, int max) {
        if (!found.find()) return;
        try {
            int value = Integer.parseInt(found.group(1));
            if (value >= min && value <= max) values.put(key, value);
        } catch (NumberFormatException ignored) { /* 범위를 벗어난 숫자는 추측하지 않는다. */ }
    }
    @Override
    public void extract(String message, String previousQuestion, ObjectNode values) {
        String text = message.trim();
        // 지역명은 지원 지역에서 정확히 하나만 일치할 때만 ID로 바꾼다.
        List<Region> regions = jdbc.query("SELECT region_id, region_name FROM region WHERE is_supported = 1 AND abolished_at IS NULL", (rs, row) -> new Region(rs.getLong(1), rs.getString(2)));
        Set<Long> matches = new HashSet<>();
        for (Region region : regions) {
            if (region.name() == null || region.name().length() < 2) continue;
            String pattern = "(?<![가-힣])" + Pattern.quote(region.name()) + "(?=으로|에서|에는|으로|에|을|를|와|과|[^가-힣]|$)";
            if (Pattern.compile(pattern).matcher(text).find()) matches.add(region.id());
        }
        if (matches.size() == 1) values.put("regionId", matches.iterator().next());
        Matcher regionNumber = match("지역\\s*번호\\s*(\\d+)", text);
        if (!regionNumber.find() && ConditionQuestions.REGION.equals(previousQuestion)) regionNumber = match("^\\s*(\\d+)\\s*(?:번)?\\s*$", text);
        else regionNumber.reset();
        if (regionNumber.find()) {
            try {
                long id = Long.parseLong(regionNumber.group(1));
                Integer count = jdbc.queryForObject("SELECT COUNT(*) FROM region WHERE region_id = ? AND is_supported = 1 AND abolished_at IS NULL", Integer.class, id);
                if (count != null && count == 1) values.put("regionId", id);
            } catch (NumberFormatException ignored) { /* 올바르지 않은 번호는 반영하지 않는다. */ }
        }
        Matcher date = match("(?<!\\d)(\\d{4}-\\d{2}-\\d{2})(?!\\d)", text);
        if (date.find() && (ConditionQuestions.DATE.equals(previousQuestion) || text.contains("출발") || text.equals(date.group(1)))) {
            try { values.put("startDate", LocalDate.parse(date.group(1)).toString()); }
            catch (DateTimeParseException ignored) { /* 존재하지 않는 날짜는 반영하지 않는다. */ }
        }
        Matcher nights = match("(?<!\\d)(\\d+)\\s*박\\s*(\\d+)\\s*일", text);
        if (nights.find()) {
            try {
                int n = Integer.parseInt(nights.group(1)), days = Integer.parseInt(nights.group(2));
                if (days == n + 1 && days >= 1 && days <= 7) values.put("durationDays", days);
            } catch (NumberFormatException ignored) { /* 지나치게 큰 숫자는 무시한다. */ }
        } else if (text.contains("당일치기") || text.equals("당일")) values.put("durationDays", 1);
        else number(values, "durationDays", match("(?<![\\d-])(\\d+)\\s*일(?:간|동안|\\s*여행|\\s*$)", text), 1, 7);
        number(values, "adults", match("성인\\s*(\\d+)\\s*명?", text), 1, 100);
        number(values, "children", match("(?:아동|어린이|아이)\\s*(\\d+)\\s*명?", text), 0, 100);
        if (ConditionQuestions.ADULTS.equals(previousQuestion)) number(values, "adults", match("^\\s*(\\d+)\\s*명?\\s*$", text), 1, 100);
        if (ConditionQuestions.CHILDREN.equals(previousQuestion)) {
            number(values, "children", match("^\\s*(\\d+)\\s*명?\\s*$", text), 0, 100);
            if (text.matches("없(?:어|어요|습니다)?[.!]?")) values.put("children", 0);
        }
        if (ConditionQuestions.DURATION.equals(previousQuestion)) number(values, "durationDays", match("^\\s*(\\d+)\\s*일?\\s*$", text), 1, 7);
        Map<String, String> companions = Map.of("혼자", "SOLO", "연인", "COUPLE", "친구", "FRIENDS", "가족", "FAMILY");
        setOne(text, values, "companionType", companions);
        Map<String, String> transport = Map.of("대중교통", "PUBLIC_TRANSPORT", "자동차", "CAR", "자차", "CAR");
        setOne(text, values, "transportType", transport);
    }
    private static void setOne(String text, ObjectNode values, String field, Map<String, String> words) {
        Set<String> found = new HashSet<>();
        words.forEach((word, code) -> { if (text.contains(word)) found.add(code); });
        if (found.size() == 1) values.put(field, found.iterator().next());
    }
}

package com.smarttraveler.chat;

import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import tools.jackson.databind.node.ObjectNode;
import java.util.List;
import java.util.Map;

/** 선택한 지역에 저장된 관광지만 후보로 전달한다. */
@Service
public class StoredPlaceCandidates {
    private final JdbcTemplate jdbc;
    public StoredPlaceCandidates(JdbcTemplate jdbc) { this.jdbc = jdbc; }
    public List<Map<String, Object>> find(ObjectNode conditions) {
        Long id = regionId(conditions);
        if (id == null) return List.of();
        return jdbc.query("SELECT p.place_id,p.name,COALESCE(p.address,'') FROM place p JOIN region r ON r.region_id=p.region_id " +
                        "WHERE (p.region_id=? OR r.parent_region_id=?) AND p.source_provider='TOURAPI' AND p.is_active=TRUE ORDER BY p.name,p.place_id LIMIT 30",
                (rs, row) -> Map.<String,Object>of("placeId", rs.getLong(1), "name", rs.getString(2), "address", rs.getString(3)), id, id);
    }
    private Long regionId(ObjectNode conditions) {
        var field = conditions.path("regionId");
        if (field.isIntegralNumber() && field.canConvertToLong() && field.asLong() > 0) return field.asLong();
        String name = conditions.path("regionName").asText("").trim();
        if (name.isEmpty() || name.length() > 100) return null;
        List<Long> exact = jdbc.query("SELECT region_id FROM region WHERE is_supported=TRUE AND abolished_at IS NULL AND (full_name=? OR region_name=?) LIMIT 2",
                (rs, row) -> rs.getLong(1), name, name);
        if (exact.size() == 1) return exact.get(0);
        if (!exact.isEmpty()) return null;
        // 시도 약칭이 하나로만 연결될 때만 후보를 찾는다.
        String prefix = name.replace("\\", "\\\\").replace("%", "\\%").replace("_", "\\_");
        List<Long> matches = jdbc.query("SELECT region_id FROM region WHERE parent_region_id IS NULL AND is_supported=TRUE AND abolished_at IS NULL AND region_name LIKE CONCAT(?, '%') LIMIT 2",
                (rs, row) -> rs.getLong(1), prefix);
        return matches.size() == 1 ? matches.get(0) : null;
    }
}

package com.smarttraveler.chat;

import org.springframework.beans.factory.annotation.Value;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.PostMapping;
import tools.jackson.databind.ObjectMapper;
import tools.jackson.databind.JsonNode;
import tools.jackson.databind.node.ObjectNode;
import org.springframework.http.HttpStatus;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.server.ResponseStatusException;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.time.Duration;

/** AI 서버의 지역·관광지 조회를 화면에 전달한다. 인증키는 전달하지 않는다. */
@RestController
@RequestMapping("/api/chat/tour")
public class TourController {
    private final String baseUrl;
    private final TourImportService importer;
    private final ObjectMapper mapper;
    private final HttpClient client = HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(5)).build();
    public TourController(@Value("${AI_SERVICE_URL:http://127.0.0.1:8001}") String baseUrl, TourImportService importer, ObjectMapper mapper) {
        this.importer = importer; this.mapper = mapper;
        this.baseUrl = baseUrl.replaceAll("/+$", "") + "/internal/tour/";
    }
    @GetMapping("/regions")
    public ResponseEntity<String> regions(@RequestParam(required = false) String province) {
        if (province != null) validateCode(province);
        return forward("regions" + (province == null ? "" : "?province=" + province));
    }
    @PostMapping("/places")
    @Transactional
    public ResponseEntity<String> places(@RequestParam String province, @RequestParam(required = false) String district,
                                          @RequestParam(defaultValue = "1") int page) {
        validateCode(province);
        if (district != null) validateCode(district);
        if (page < 1 || page > 100) throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "페이지를 확인해 주세요.");
        ResponseEntity<String> response = forward("places?province=" + province + (district == null ? "" : "&district=" + district) + "&page=" + page);
        try {
            JsonNode body = mapper.readTree(response.getBody());
            if (!(body instanceof ObjectNode object)) throw new IllegalArgumentException("관광정보 응답이 올바르지 않습니다.");
            if (!province.equals(object.path("province").path("code").asText()) ||
                    (district != null && !district.equals(object.path("district").path("code").asText())))
                throw new IllegalArgumentException("조회한 지역 코드가 요청과 일치하지 않습니다.");
            importer.save(object);
            return ResponseEntity.ok().contentType(MediaType.APPLICATION_JSON).body(mapper.writeValueAsString(object));
        } catch (RuntimeException ex) {
            throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE, "관광정보를 저장하지 못했습니다. 다시 시도해 주세요.");
        }
    }
    private static void validateCode(String code) {
        if (code == null || !code.matches("[0-9]{1,5}")) throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "지역 코드를 확인해 주세요.");
    }
    private ResponseEntity<String> forward(String path) {
        HttpRequest request = HttpRequest.newBuilder(URI.create(baseUrl + path)).timeout(Duration.ofSeconds(20)).GET().build();
        try {
            HttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());
            if (response.statusCode() != 200) throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE, "관광정보를 불러오지 못했습니다.");
            return ResponseEntity.ok().contentType(MediaType.APPLICATION_JSON).body(response.body());
        } catch (InterruptedException ex) {
            Thread.currentThread().interrupt();
            throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE, "관광정보 요청이 중단되었습니다.");
        } catch (java.io.IOException ex) {
            throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE, "관광정보 서버에 연결할 수 없습니다.");
        }
    }
}

package com.smarttraveler.chat;

import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.stereotype.Service;
import tools.jackson.databind.JsonNode;
import tools.jackson.databind.node.ObjectNode;
import java.math.BigDecimal;
import java.sql.Statement;
import java.util.List;
import java.util.Objects;

/** 관광공사 코드와 기존 지역·장소 ID를 연결해 조회한 항목을 저장한다. */
@Service
public class TourImportService {
    private final JdbcTemplate jdbc;
    public TourImportService(JdbcTemplate jdbc) { this.jdbc = jdbc; }

    public void save(ObjectNode data) {
        JsonNode province = data.path("province"), district = data.path("district"), items = data.path("items");
        String provinceCode = code(province.path("code")), provinceName = required(province.path("name"), 100);
        if (!items.isArray()) throw new IllegalArgumentException("관광지 목록 형식이 올바르지 않습니다.");
        long provinceId = region("TOUR_SIDO", provinceCode, provinceName, provinceName, null);
        Long districtId = null;
        if (district.isObject()) {
            String districtCode = code(district.path("code")), districtName = required(district.path("name"), 100);
            districtId = region("TOUR_SIGUNGU", provinceCode + ":" + districtCode, districtName, provinceName + " " + districtName, provinceId);
        }
        data.put("regionId", districtId == null ? provinceId : districtId);
        for (JsonNode item : items) {
            if (!(item instanceof ObjectNode object)) throw new IllegalArgumentException("관광지 형식이 올바르지 않습니다.");
            String sourceId = required(item.path("id"), 100), name = required(item.path("name"), 200);
            String areaCode = item.path("districtCode").asText("").trim();
            long regionId = provinceId;
            boolean hasDistrict = !areaCode.isEmpty();
            if (hasDistrict) {
                if (!areaCode.matches("[0-9]{1,5}")) throw new IllegalArgumentException("시군구 코드가 올바르지 않습니다.");
                String areaName = required(item.path("districtName"), 100);
                regionId = region("TOUR_SIGUNGU", provinceCode + ":" + areaCode, areaName, provinceName + " " + areaName, provinceId);
            }
            String address = optional(item.path("address"), 300), phone = optional(item.path("phone"), 30);
            BigDecimal latitude = coordinate(item.path("latitude"), 90), longitude = coordinate(item.path("longitude"), 180);
            // 중복 자료는 API 식별자로 갱신하고 수동 상태·설명·이미지는 건드리지 않는다.
            jdbc.update("INSERT INTO place (region_id,source_provider,source_place_id,place_type,name,address,latitude,longitude,phone,is_active,verification_status,last_synced_at,updated_at) " +
                    "VALUES (?, 'TOURAPI', ?, 'ATTRACTION', ?, ?, ?, ?, ?, TRUE, 'UNVERIFIED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) " +
                    "ON DUPLICATE KEY UPDATE region_id=IF(?,VALUES(region_id),region_id),name=VALUES(name),address=COALESCE(VALUES(address),address),latitude=COALESCE(VALUES(latitude),latitude),longitude=COALESCE(VALUES(longitude),longitude),phone=COALESCE(VALUES(phone),phone),last_synced_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP",
                    regionId, sourceId, name, address, latitude, longitude, phone, hasDistrict);
            Long placeId = jdbc.queryForObject("SELECT place_id FROM place WHERE source_provider='TOURAPI' AND source_place_id=?", Long.class, sourceId);
            object.put("placeId", Objects.requireNonNull(placeId));
        }
    }
    private long region(String provider, String external, String name, String fullName, Long parent) {
        // 외부 코드 행을 먼저 잠가 동시 요청 시 같은 지역을 두 번 만들지 않는다.
        jdbc.update("INSERT INTO region_external_code (provider,external_code,region_id) VALUES (?,?,NULL) ON DUPLICATE KEY UPDATE external_code=VALUES(external_code)", provider, external);
        List<Long> mapped = jdbc.query("SELECT region_id FROM region_external_code WHERE provider=? AND external_code=? FOR UPDATE", (rs, row) -> (Long) rs.getObject(1), provider, external);
        if (mapped.size() != 1) throw new IllegalStateException("지역 매핑을 확인할 수 없습니다.");
        if (mapped.get(0) != null) return mapped.get(0);
        List<Long> matches = parent == null
                ? jdbc.query("SELECT region_id FROM region WHERE parent_region_id IS NULL AND full_name=?", (rs, row) -> rs.getLong(1), fullName)
                : jdbc.query("SELECT region_id FROM region WHERE parent_region_id=? AND full_name=?", (rs, row) -> rs.getLong(1), parent, fullName);
        if (matches.size() > 1) throw new IllegalStateException("같은 이름의 기존 지역이 여러 개입니다.");
        long id;
        if (matches.size() == 1) id = matches.get(0);
        else {
            var key = new GeneratedKeyHolder();
            jdbc.update(connection -> {
                var statement = connection.prepareStatement("INSERT INTO region (region_code,region_name,full_name,region_level,parent_region_id,is_supported,updated_at) VALUES (?,?,?,?,?,TRUE,CURRENT_TIMESTAMP)", Statement.RETURN_GENERATED_KEYS);
                statement.setString(1, "KTO-" + external.replace(':', '-')); statement.setString(2, name); statement.setString(3, fullName);
                statement.setString(4, parent == null ? "CITY" : "DISTRICT");
                if (parent == null) statement.setNull(5, java.sql.Types.BIGINT); else statement.setLong(5, parent);
                return statement;
            }, key);
            id = Objects.requireNonNull(key.getKey()).longValue();
        }
        jdbc.update("UPDATE region_external_code SET region_id=? WHERE provider=? AND external_code=?", id, provider, external);
        return id;
    }
    private static String required(JsonNode node, int max) {
        if (!node.isTextual()) throw new IllegalArgumentException("관광정보 필수 항목이 없습니다.");
        String value = node.asText().trim();
        if (value.isEmpty() || value.length() > max) throw new IllegalArgumentException("관광정보 필수 항목이 올바르지 않습니다.");
        return value;
    }
    private static String optional(JsonNode node, int max) {
        if (!node.isTextual() || node.asText().isBlank()) return null;
        String value = node.asText().trim();
        return value.length() <= max ? value : value.substring(0, max);
    }
    private static String code(JsonNode node) {
        String value = required(node, 5);
        if (!value.matches("[0-9]{1,5}")) throw new IllegalArgumentException("지역 코드가 올바르지 않습니다.");
        return value;
    }
    private static BigDecimal coordinate(JsonNode value, int maximum) {
        try {
            BigDecimal decimal = new BigDecimal(value.asText(""));
            if (decimal.signum() == 0 || decimal.abs().compareTo(BigDecimal.valueOf(maximum)) > 0) return null;
            return decimal;
        } catch (NumberFormatException ex) { return null; }
    }
}

