package com.smarttraveler.recommendation.dto;

import java.time.LocalDate;
import java.time.LocalTime;
import java.util.List;
import java.util.UUID;

/** 추천과 향후 수정 기능이 함께 사용할 코스 초안 형식이다. */
public record CourseDraft(
