package com.smarttraveler.admin;

import jakarta.persistence.Column;
import jakarta.persistence.Transient;
import java.lang.reflect.Field;
import java.lang.reflect.Modifier;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.stream.Collectors;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.assertTrue;

class AdminTeamColumnAlignmentTest {
    @Test
    void adminMappingsDoNotAddColumnsToTeamTables() {
        var pairs = List.of(
            Map.entry(com.smarttraveler.admin.data.Course.class, com.smarttraveler.domain.entity.Course.class),
            Map.entry(com.smarttraveler.admin.data.CourseTemplate.class, com.smarttraveler.domain.entity.CourseTemplate.class),
            Map.entry(com.smarttraveler.admin.data.GenerationMethod.class, com.smarttraveler.domain.entity.GenerationMethod.class),
            Map.entry(com.smarttraveler.admin.data.Lodging.class, com.smarttraveler.domain.entity.Lodging.class),
            Map.entry(com.smarttraveler.admin.data.Member.class, com.smarttraveler.domain.entity.Member.class),
            Map.entry(com.smarttraveler.admin.data.MemberSuspensionHistory.class, com.smarttraveler.domain.entity.MemberSuspensionHistory.class),
            Map.entry(com.smarttraveler.admin.data.OwnerProfile.class, com.smarttraveler.domain.entity.OwnerProfile.class),
            Map.entry(com.smarttraveler.admin.data.OwnerReviewHistory.class, com.smarttraveler.domain.entity.OwnerReviewHistory.class),
            Map.entry(com.smarttraveler.admin.data.OwnerReviewStatus.class, com.smarttraveler.domain.entity.OwnerReviewStatus.class),
            Map.entry(com.smarttraveler.admin.data.Payment.class, com.smarttraveler.domain.entity.RoomPayment.class),
            Map.entry(com.smarttraveler.admin.data.Reservation.class, com.smarttraveler.domain.entity.RoomReservation.class),
            Map.entry(com.smarttraveler.admin.data.Room.class, com.smarttraveler.domain.entity.Room.class),
            Map.entry(com.smarttraveler.admin.data.RoomInventory.class, com.smarttraveler.domain.entity.RoomInventory.class),
            Map.entry(com.smarttraveler.admin.data.HumanCourse.class, com.smarttraveler.domain.entity.HumanCoursePost.class),
            Map.entry(com.smarttraveler.admin.data.HumanReport.class, com.smarttraveler.domain.entity.HumanCourseReport.class)
        );
        for (var pair : pairs) {
            Set<String> team = columns(pair.getValue());
            Set<String> admin = columns(pair.getKey());
            admin.removeAll(team);
            assertTrue(admin.isEmpty(), pair.getKey().getSimpleName() + " adds " + admin);
        }
    }

    private static Set<String> columns(Class<?> type) {
        return java.util.Arrays.stream(type.getDeclaredFields())
            .filter(f -> !Modifier.isStatic(f.getModifiers()))
            .filter(f -> !f.isAnnotationPresent(Transient.class))
            .filter(f -> !f.isAnnotationPresent(jakarta.persistence.ManyToOne.class))
            .filter(f -> !f.isAnnotationPresent(jakarta.persistence.OneToMany.class))
            .map(AdminTeamColumnAlignmentTest::column)
            .collect(Collectors.toSet());
    }
    private static String column(Field field) {
        Column c = field.getAnnotation(Column.class);
        if (c != null && !c.name().isEmpty()) return c.name();
        return field.getName().replaceAll("([a-z0-9])([A-Z])", "$1_$2").toLowerCase();
    }
}

package com.smarttraveler.auth;

import com.smarttraveler.domain.entity.Member;
import java.time.LocalDateTime;
import java.util.Optional;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.context.annotation.Import;
import org.springframework.mock.web.MockHttpSession;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.security.web.csrf.CsrfToken;
import org.springframework.test.context.junit.jupiter.SpringJUnitConfig;
import org.springframework.test.context.web.WebAppConfiguration;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.setup.MockMvcBuilders;
import org.springframework.web.context.WebApplicationContext;
import org.springframework.web.servlet.config.annotation.EnableWebMvc;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.csrf;
import static org.springframework.security.test.web.servlet.setup.SecurityMockMvcConfigurers.springSecurity;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;

// Uses real Security filters and BCrypt with a mocked repository. No database writes.
@SpringJUnitConfig(AuthFlowTest.TestConfig.class)
@WebAppConfiguration
class AuthFlowTest {
    @Configuration
    @EnableWebMvc
    @Import({AuthSecurityConfig.class, MemberDetailsService.class, AuthController.class})
    static class TestConfig {
        @Bean MemberRepository memberRepository() { return mock(MemberRepository.class); }
    }
    @Autowired WebApplicationContext context;
    @Autowired MemberRepository repository;
    @Autowired PasswordEncoder encoder;
    MockMvc mvc;
    Member member;

    @BeforeEach
    void setup() {
        reset(repository);
        member = new Member();
        member.setMemberId(7L);
        member.setLoginId("test-traveler");
        member.setPassword(encoder.encode("Test-password-123!"));
        member.setNickname("여행자");
        member.setStatus("ACTIVE");
        member.setRoleCode("USER");
        when(repository.findByLoginId("test-traveler")).thenReturn(Optional.of(member));
        mvc = MockMvcBuilders.webAppContextSetup(context).apply(springSecurity()).build();
    }

    private MockHttpSession login() throws Exception {
        return (MockHttpSession) mvc.perform(post("/api/auth/login").with(csrf())
                .param("loginId", "test-traveler").param("password", "Test-password-123!"))
                .andExpect(status().isOk()).andReturn().getRequest().getSession(false);
    }

    @Test void anonymousCannotReadMember() throws Exception {
        mvc.perform(get("/api/auth/me")).andExpect(status().isUnauthorized());
    }
    @Test void loginNeedsCsrf() throws Exception {
        mvc.perform(post("/api/auth/login").param("loginId", "test-traveler")
                .param("password", "Test-password-123!"))
                .andExpect(status().isForbidden());
        verifyNoInteractions(repository);
    }
    @Test void realCsrfTokenLoginRotatesSessionAndReturnsOnlySafeFields() throws Exception {
        var csrfResult = mvc.perform(get("/api/auth/csrf"))
                .andExpect(status().isOk()).andExpect(jsonPath("$.token").isString()).andReturn();
        var session = (MockHttpSession) csrfResult.getRequest().getSession(false);
        var token = (CsrfToken) csrfResult.getRequest().getAttribute(CsrfToken.class.getName());
        String oldId = session.getId();
        var result = mvc.perform(post("/api/auth/login").session(session)
                .header(token.getHeaderName(), token.getToken())
                .param("loginId", "test-traveler").param("password", "Test-password-123!"))
                .andExpect(status().isOk()).andExpect(jsonPath("$.authenticated").value(true)).andReturn();
        var authenticated = (MockHttpSession) result.getRequest().getSession(false);
        assertNotEquals(oldId, authenticated.getId());
        assertEquals(1800, authenticated.getMaxInactiveInterval());
        mvc.perform(get("/api/auth/me").session(authenticated)).andExpect(status().isOk())
                .andExpect(jsonPath("$.memberId").value(7))
                .andExpect(jsonPath("$.nickname").value("여행자"))
                .andExpect(jsonPath("$.roleCode").value("USER"))
                .andExpect(jsonPath("$.password").doesNotExist());
    }
    @Test void wrongPasswordAndUnknownUserHaveSameFailure() throws Exception {
        String first = mvc.perform(post("/api/auth/login").with(csrf())
                .param("loginId", "test-traveler").param("password", "wrong"))
                .andExpect(status().isUnauthorized()).andReturn().getResponse().getContentAsString();
        String second = mvc.perform(post("/api/auth/login").with(csrf())
                .param("loginId", "missing").param("password", "wrong"))
                .andExpect(status().isUnauthorized()).andReturn().getResponse().getContentAsString();
        assertEquals(first, second);
    }
    @Test void suspendedMemberCannotLogin() throws Exception {
        member.setStatus("BANNED");
        mvc.perform(post("/api/auth/login").with(csrf()).param("loginId", "test-traveler")
                .param("password", "Test-password-123!")).andExpect(status().isUnauthorized());
    }
    @Test void deletedMemberCannotLogin() throws Exception {
        member.setDeletedAt(LocalDateTime.now());
        mvc.perform(post("/api/auth/login").with(csrf()).param("loginId", "test-traveler")
                .param("password", "Test-password-123!")).andExpect(status().isUnauthorized());
    }
    @Test void plaintextDatabasePasswordsAreNotAccepted() throws Exception {
        member.setPassword("Test-password-123!");
        mvc.perform(post("/api/auth/login").with(csrf()).param("loginId", "test-traveler")
                .param("password", "Test-password-123!")).andExpect(status().isUnauthorized());
    }
    @Test void logoutRequiresCsrfAndInvalidatesSession() throws Exception {
        var session = login();
        mvc.perform(post("/api/auth/logout").session(session)).andExpect(status().isForbidden());
        mvc.perform(get("/api/auth/me").session(session)).andExpect(status().isOk());
        mvc.perform(post("/api/auth/logout").session(session).with(csrf())).andExpect(status().isNoContent());
        assertTrue(session.isInvalid());
        mvc.perform(get("/api/auth/me")).andExpect(status().isUnauthorized());
    }
    @Test void disabledMemberIsRejectedOnSessionRefresh() throws Exception {
        var session = login();
        member.setStatus("BANNED");
        mvc.perform(get("/api/auth/me").session(session)).andExpect(status().isUnauthorized());
        assertTrue(session.isInvalid());
    }
}

package com.smarttraveler.chat;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import tools.jackson.databind.json.JsonMapper;
import tools.jackson.databind.node.ObjectNode;
import java.util.List;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;

class ConditionDialogueTest {
    private JdbcTemplate jdbc;
    private RuleBasedConditionExtractor extractor;
    private final ConditionQuestions questions = new ConditionQuestions();
    private ObjectNode conditions;
    @BeforeEach
    @SuppressWarnings("unchecked")
    void 준비() {
        jdbc = mock(JdbcTemplate.class);
        when(jdbc.query(anyString(), any(RowMapper.class))).thenReturn(List.of());
        when(jdbc.queryForObject(anyString(), eq(Integer.class), any())).thenReturn(1);
        extractor = new RuleBasedConditionExtractor(jdbc);
        conditions = JsonMapper.builder().build().createObjectNode();
        conditions.putNull("regionId"); conditions.put("startDate", ""); conditions.putNull("durationDays");
        conditions.putNull("adults"); conditions.putNull("children"); conditions.put("companionType", ""); conditions.put("transportType", "");
        conditions.put("flowType", "COURSE_FIRST");
    }
    @Test void 명확한_표현을_합치고_부족한_조건을_질문한다() {
        extractor.extract("지역 번호 1, 2026-12-10 출발, 친구와 2박 3일, 성인 2명", "", conditions);
        assertEquals(1, conditions.path("regionId").asInt());
        assertEquals("2026-12-10", conditions.path("startDate").asText());
        assertEquals(3, conditions.path("durationDays").asInt());
        assertEquals("FRIENDS", conditions.path("companionType").asText());
        assertEquals(2, conditions.path("adults").asInt());
        assertEquals(ConditionQuestions.CHILDREN, questions.next(conditions));
        extractor.extract("없어요", ConditionQuestions.CHILDREN, conditions);
        assertEquals(0, conditions.path("children").asInt());
        assertEquals(ConditionQuestions.TRANSPORT, questions.next(conditions));
        extractor.extract("자차", ConditionQuestions.TRANSPORT, conditions);
        assertEquals(ConditionQuestions.CHECK, questions.next(conditions));
    }
    @Test void 모호한_인원은_성인이나_아동으로_추측하지_않는다() {
        extractor.extract("친구 2명이랑 가요", "", conditions);
        assertTrue(conditions.path("adults").isNull());
        assertTrue(conditions.path("children").isNull());
        assertEquals("FRIENDS", conditions.path("companionType").asText());
    }
    @Test void 일반_일정의_날짜를_출발일로_추측하지_않는다() {
        extractor.extract("2026-12-10에 공연을 볼래요", "", conditions);
        assertEquals("", conditions.path("startDate").asText());
        extractor.extract("2026-12-10", ConditionQuestions.DATE, conditions);
        assertEquals("2026-12-10", conditions.path("startDate").asText());
    }
    @Test void 확인한_기존_값은_새_정보가_없으면_유지한다() {
        conditions.put("durationDays", 3); conditions.put("adults", 2);
        extractor.extract("좋아요", "", conditions);
        assertEquals(3, conditions.path("durationDays").asInt());
        assertEquals(2, conditions.path("adults").asInt());
    }
    @Test void 잘못된_날짜와_일수는_반영하지_않는다() {
        extractor.extract("2026-02-30 출발, 2박 7일", "", conditions);
        assertEquals("", conditions.path("startDate").asText());
        assertTrue(conditions.path("durationDays").isNull());
    }
    @Test void 등록되지_않은_지역_번호는_반영하지_않는다() {
        when(jdbc.queryForObject(anyString(), eq(Integer.class), any())).thenReturn(0);
        extractor.extract("지역 번호 99999", "", conditions);
        assertTrue(conditions.path("regionId").isNull());
        assertEquals(ConditionQuestions.REGION, questions.next(conditions));
    }
}

package com.smarttraveler.chat;

import org.junit.jupiter.api.Test;
import org.springframework.http.HttpStatus;
import org.springframework.web.server.ResponseStatusException;
import tools.jackson.databind.ObjectMapper;
import tools.jackson.databind.json.JsonMapper;
import tools.jackson.databind.node.ObjectNode;
import java.util.Map;
import static org.junit.jupiter.api.Assertions.*;

class OpenAiConditionExtractorTest {
    private final ObjectMapper mapper = JsonMapper.builder().build();
    private String response(String json) {
        return mapper.writeValueAsString(Map.of("status", "completed", "output", java.util.List.of(Map.of("type", "message", "content", java.util.List.of(Map.of("type", "output_text", "text", json))))));
    }
    @Test void 명시된_조건을_병합하고_지역번호는_만들지_않는다() {
        String reply = """
                {"regionName":"부산","startDate":null,"durationDays":3,"adults":null,"children":null,"companionType":"FRIENDS","transportType":null,"preferences":["바다"]}
                """;
        String[] request = {null};
        var extractor = new OpenAiConditionExtractor(body -> { request[0] = body; return response(reply); }, mapper, "test-model");
        ObjectNode values = mapper.createObjectNode(); values.put("adults", 2); values.putNull("regionId");
        extractor.extract("친구와 부산 2박 3일, 바다가 좋아요", "", values);
        assertEquals("부산", values.path("regionName").asText());
        assertTrue(values.path("regionId").isNull());
        assertEquals(3, values.path("durationDays").asInt());
        assertEquals(2, values.path("adults").asInt());
        assertEquals("FRIENDS", values.path("companionType").asText());
        assertEquals("바다", values.path("preferences").get(0).asText());
        JsonNodeAssertions.check(mapper, request[0]);
    }
    @Test void 잘못된_값은_기존값을_덮어쓰지_않는다() {
        String reply = """
                {"regionName":null,"startDate":"2026-02-30","durationDays":99,"adults":-1,"children":-1,"companionType":"INVALID","transportType":"INVALID","preferences":null}
                """;
        var extractor = new OpenAiConditionExtractor(body -> response(reply), mapper, "test-model");
        ObjectNode values = mapper.createObjectNode(); values.put("startDate", "2026-12-10"); values.put("durationDays", 3); values.put("adults", 2); values.put("companionType", "FAMILY");
        extractor.extract("내용", "", values);
        assertEquals("2026-12-10", values.path("startDate").asText());
        assertEquals(3, values.path("durationDays").asInt());
        assertEquals(2, values.path("adults").asInt());
        assertEquals("FAMILY", values.path("companionType").asText());
    }
    @Test void 지역이_바뀌면_기존_지역번호를_제거한다() {
        String reply = """
                {"regionName":"제주","startDate":null,"durationDays":null,"adults":null,"children":null,"companionType":null,"transportType":null,"preferences":null}
                """;
        var extractor = new OpenAiConditionExtractor(body -> response(reply), mapper, "test-model");
        ObjectNode values = mapper.createObjectNode(); values.put("regionName", "부산"); values.put("regionId", 1);
        extractor.extract("제주로 바꿀게요", "", values);
        assertEquals("제주", values.path("regionName").asText()); assertTrue(values.path("regionId").isNull());
    }
    @Test void 거절이나_미완료_응답은_실패로_처리한다() {
        var extractor = new OpenAiConditionExtractor(body -> "{\"status\":\"incomplete\",\"output\":[]}", mapper, "test-model");
        var ex = assertThrows(ResponseStatusException.class, () -> extractor.extract("부산", "", mapper.createObjectNode()));
        assertEquals(HttpStatus.SERVICE_UNAVAILABLE, ex.getStatusCode());
    }
    @Test void 키가_없으면_외부로_요청하지_않고_안내한다() {
        var transport = new OpenAiHttpTransport("");
        var ex = assertThrows(ResponseStatusException.class, () -> transport.request("{}"));
        assertEquals(HttpStatus.SERVICE_UNAVAILABLE, ex.getStatusCode());
    }
    private static class JsonNodeAssertions {
        static void check(ObjectMapper mapper, String request) {
            var body = mapper.readTree(request);
            assertFalse(body.path("store").asBoolean());
            assertEquals("json_schema", body.path("text").path("format").path("type").asText());
            assertTrue(body.path("text").path("format").path("strict").asBoolean());
        }
    }
}

package com.smarttraveler.domain;

import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.config.BeanDefinition;
import org.springframework.context.annotation.ClassPathScanningCandidateComponentProvider;
import org.springframework.core.type.filter.AnnotationTypeFilter;

import java.lang.reflect.Field;
import java.util.Arrays;
import java.util.Set;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

class EntityMappingTest {
    @Test
    void allExerdTablesHaveEntitiesAndPrimaryKeys() throws Exception {
        ClassPathScanningCandidateComponentProvider scanner =
                new ClassPathScanningCandidateComponentProvider(false);
        scanner.addIncludeFilter(new AnnotationTypeFilter(Entity.class));
        Set<BeanDefinition> entities =
                scanner.findCandidateComponents("com.smarttraveler.domain.entity");
        assertEquals(63, entities.size());
        for (BeanDefinition definition : entities) {
            Class<?> entityClass = Class.forName(definition.getBeanClassName());
            boolean hasId = Arrays.stream(entityClass.getDeclaredFields())
                    .map(Field::getAnnotations)
                    .flatMap(Arrays::stream)
                    .anyMatch(annotation -> annotation.annotationType() == Id.class);
            assertTrue(hasId, entityClass.getSimpleName() + " must declare an @Id field");
        }
    }
}

package com.smarttraveler.recommendation;

import com.smarttraveler.recommendation.dto.RecommendationRequest;
import com.smarttraveler.recommendation.service.RecommendationService;
import jakarta.validation.Validation;
import org.junit.jupiter.api.Test;
import org.springframework.http.HttpStatus;
import org.springframework.web.server.ResponseStatusException;

import java.time.LocalDate;
import java.time.LocalTime;
import java.util.List;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

class RecommendationServiceTest {
    private final RecommendationService service = new RecommendationService();

    private RecommendationRequest request(List<RecommendationRequest.FixedEvent> fixedEvents) {
        return new RecommendationRequest(1L, LocalDate.of(2026, 11, 14), 2, 2, 0,
                "FRIENDS", "PUBLIC_TRANSPORT", List.of("바다"), fixedEvents, "COURSE_FIRST", null);
    }

    @Test
    void 실제_연결_전에는_추천_성공으로_응답하지_않는다() {
        var error = assertThrows(ResponseStatusException.class, () -> service.recommend(request(List.of())));
        assertEquals(HttpStatus.SERVICE_UNAVAILABLE, error.getStatusCode());
    }

    @Test
    void 여행_기간_밖의_고정_일정은_거부한다() {
        var event = new RecommendationRequest.FixedEvent(LocalDate.of(2026, 11, 16), LocalTime.of(10, 0), "공연");
        var error = assertThrows(ResponseStatusException.class, () -> service.recommend(request(List.of(event))));
        assertEquals(HttpStatus.BAD_REQUEST, error.getStatusCode());
    }

    @Test
    void 숙소_먼저_조건에는_선택한_숙소가_필요하다() {
        var request = new RecommendationRequest(1L, LocalDate.of(2026, 11, 14), 2, 2, 0,
                "FRIENDS", "PUBLIC_TRANSPORT", List.of(), List.of(), "STAY_FIRST", null);
        try (var factory = Validation.buildDefaultValidatorFactory()) {
            var violations = factory.getValidator().validate(request);
            assertTrue(violations.stream().anyMatch(violation ->
                    violation.getMessage().contains("숙소 먼저 방식")));
        }
    }
}

